function tile(g){const m=model(g.h,g.a,g.aud?SA:S,g.aud),b=g.aud?null:bestOf(g,m);let tag;
 if(g.aud){const r=AR(g,m);tag=`<b style="color:var(--${r.ok==2?"mut":r.ok?"ok":"bad"})">${r.ok==2?"PUSH":r.ok?"✓":"✗"} ${g.sc[0]}–${g.sc[1]}</b>`}else tag=`<b>${pc(b?b.o.p:m.cp.p)}</b>`;
 return `<div class="tile" data-open="${g.k}"><div class="mt"><div class="tm">${window.MS?MS(g.h):""}${g.h}<small>LOCAL</small></div><span class="pkc"></span><div class="tm" style="text-align:right">${window.MS?MS(g.a,1):""}${g.a}<small>VISITA</small></div></div>
 <div class="meta"><span>${g.t||"Simulación"}${g.ref?` · ref. ${g.ref}%`:""}</span><span>Proy ${m.lh.toFixed(1)}–${m.la.toFixed(1)}</span></div>
 <div class="tp"><span>${b?"MEJOR VALOR":g.aud?"PICK PRE-JUEGO":"PICK"}</span><div>${g.aud?AR(g,m).l:b?b.o.l:m.cp.l}</div>${tag}</div><div class="go">ANALIZAR ▸</div></div>`}
let OPEN=null,TMR=[];
function lines(g){const SS=g.aud?SA:S,m=model(g.h,g.a,SS,g.aud),f=v=>v.toFixed(1),q=v=>(v*100).toFixed(1)+"%";
 return [`Sincronizando temporada 2025 + ${SS[g.h].n+SS[g.a].n} juegos de 2026`,
 `Ofensiva/defensiva (pts por juego) · ${g.h} ${f(m.H.rs)}/${f(m.H.ra)} · ${g.a} ${f(m.A.rs)}/${f(m.A.ra)}`,
 g.aud?"Modo auditoría · sin reporte de lesiones":`Leyendo reporte de lesiones · ${m.notes.length} ajustes activos`,
 `Pitágoras 2.37 · ${q(m.x)} vs ${q(m.y)}`,
 `Log5 + ventaja local ${NEUT.has(g.h+"-"+g.a)?"neutral (Londres)":"55%"} → ${g.h} ${q(m.pH)}`,
 `Puntos proyectados ${f(m.lh)}–${f(m.la)} · total ${f(m.tot)}`,
 `Spread del modelo: ${m.mu>=0?g.h:g.a} −${Math.abs(m.mu).toFixed(1)} · curva normal`,
 "Escaneando 14 mercados · buscando valor",
 `Pick del modelo: ${m.cp.l} (${q(m.cp.p)})`,
 "ANÁLISIS COMPLETO"]}
